            for r2, c2 in cells[i + 1:]:
                dr, dc = r2-r1, c2-c1
                if not dr or abs(dr) != abs(dc):
                    continue

                # Do not extend the diagonal pair when it is one diagonal
                # of a compact crossing/two-by-two multicolor motif.
                if abs(dr) == 1:
                    other = (grid[r1][c2], grid[r2][c1])
                    if all(x != bg and x != color for x in other):
                        continue

                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for r, c, vr, vc in (
                    (r1-sr, c1-sc, -sr, -sc),
                    (r2+sr, c2+sc, sr, sc)
                ):
                    while 0 <= r < h and 0 <= c < w:
                        if grid[r][c] != bg:
                            break
                        out[r][c] = color
                        r += vr
                        c += vc
    return out
